diff --git a/tests/notes.test.mjs b/tests/notes.test.mjs
index b43658e..a2c70b0 100644
--- a/tests/notes.test.mjs
+++ b/tests/notes.test.mjs
@@ -26,6 +26,21 @@ test('a note without a title is rejected', async () => {
   assert.equal((await call('POST', '/notes', 'ayse', { body: 'x' })).status, 400);
 });

+test('GET /notes returns the newest note first', async () => {
+  const mk = (title, createdAt) => call('POST', '/notes', 'ayse', { title, createdAt });
+  await mk('sort-b', '2024-01-02T10:00:00Z');
+  await mk('sort-d', '2024-01-03T12:00:00+05:00'); // 07:00Z: older than sort-c, though its string sorts later
+  await mk('sort-a', '2024-01-01T10:00:00Z');
+  await mk('sort-c', '2024-01-03T10:00:00Z');
+  await call('POST', '/notes', 'ayse', { title: 'sort-now' });
+  const titles = (await (await call('GET', '/notes', 'ayse')).json()).map((n) => n.title).filter((t) => t.startsWith('sort-'));
+  assert.deepEqual(titles, ['sort-now', 'sort-c', 'sort-d', 'sort-b', 'sort-a']);
+});
+
+test('an invalid createdAt is rejected', async () => {
+  assert.equal((await call('POST', '/notes', 'ayse', { title: 'x', createdAt: 'dün' })).status, 400);
+});
+
 test('a note can be updated and deleted', async () => {
   const note = await (await call('POST', '/notes', 'ayse', { title: 'Taslak' })).json();
   assert.equal((await (await call('PATCH', `/notes/${note.id}`, 'ayse', { title: 'Son' })).json()).title, 'Son');

